"""Build all published files using only Python's standard library."""
from pathlib import Path
from html import escape as E
import json, shutil
from cloud import PROVIDERS,ROLES,NOTES,EXTRA,choice,svg
ROOT=Path(__file__).resolve().parent
OUT=ROOT/'dist'
DATA=json.loads((ROOT/'content.json').read_text())
ITEMS=DATA['architectures'];CATS=DATA['categories'];SOURCES=DATA['sources']
NAMES={c['id']:c['title'] for c in CATS}
OUT.mkdir(exist_ok=True);(OUT/'diagrams').mkdir(exist_ok=True)

def page(path,title,body,depth=0):
 pre='../'*depth
 doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="A research reference for AI system design with AWS, Google Cloud, and Azure implementation diagrams."><title>{E(title)} · AI System Design Atlas</title><link rel="icon" type="image/svg+xml" href="{pre}diagrams/icon.svg"><link rel="stylesheet" href="{pre}style.css"><script defer src="{pre}site.js"></script></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="{pre}index.html"><span aria-hidden="true">▦</span> AI System Design Atlas</a><nav aria-label="Main navigation"><a href="{pre}index.html#explore">Categories</a><a href="{pre}architectures.html">Architecture index</a><a href="{pre}about.html">Method & sources</a></nav></header><main id="main">{body}</main><footer><span>20 shared patterns · 6 overlapping categories</span><a href="{pre}about.html">Research notes · October 2026</a><a href="https://github.com/LazyBuilder/AI-System-Design-Atlas-KB">GitHub repository ↗</a></footer></body></html>'''
 dest=OUT/path;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(doc)

def chips(x,pre=''):
 return '<div class="chips">'+''.join(f'<a href="{pre}categories/{c}/index.html">{NAMES[c]}</a>' for c in x['categories'])+'</div>'

def card(x,pre=''):
 return f'<article class="card"><span class="eyebrow">PATTERN {ITEMS.index(x)+1:02d}</span><h3><a href="{pre}architectures/{x["id"]}/index.html">{x["title"]} →</a></h3><p>{x["description"]}</p>'+chips(x,pre)+'</article>'

def breadcrumb(title,category=False):
 middle='<span>Categories</span>' if category else '<a href="../../architectures.html">Architectures</a>'
 return f'<nav class="breadcrumb" aria-label="Breadcrumb"><a href="../../index.html">Atlas</a><span>/</span>{middle}<span>/</span><span aria-current="page">{E(title)}</span></nav>'

def implementation(x):
 b='<section id="implementation" class="implementation"><span class="eyebrow">IMPLEMENTATION REFERENCE</span><h2>Map the building blocks to a cloud</h2><p>Choose a provider to see service suggestions beside each block. These are illustrative compositions, not identical service offerings or complete deployment templates.</p><div class="provider-switch" role="group" aria-label="Cloud provider">'
 for p,name in PROVIDERS.items():
  label='GCP · Google Cloud' if p=='gcp' else name
  b+=f'<button type="button" data-provider="{p}" aria-controls="panel-{p}" aria-pressed="{str(p=="aws").lower()}">{label}</button>'
 b+='</div><noscript><p class="callout">JavaScript is disabled. All three cloud references are visible below.</p></noscript>'
 for p,name in PROVIDERS.items():
  file=f'{x["id"]}-{p}.svg';(OUT/'diagrams'/file).write_text(svg(x,p))
  b+=f'<section class="provider-panel" id="panel-{p}" aria-labelledby="heading-{p}"><h3 id="heading-{p}">{name} implementation</h3><figure><div class="diagram-scroll" tabindex="0" role="region" aria-label="Scrollable system diagram"><img src="../../diagrams/{file}" width="1280" height="420" alt="{E(x["title"])} on {name}: {E(" → ".join(x["flow"]))}. Service details follow in the table."></div><figcaption>Simplified logical flow · <a href="../../diagrams/{file}">Open full-size diagram ↗</a></figcaption></figure><div class="table-scroll" tabindex="0" role="region" aria-label="Scrollable service mapping"><table><caption>Building blocks and services — {name}</caption><thead><tr><th scope="col">Building block</th><th scope="col">Service / component</th><th scope="col">Implementation responsibility</th></tr></thead><tbody>'
  for i,(label,role) in enumerate(zip(x['flow'],ROLES[x['id']])):
   s=choice(role,p)
   value=f'<a href="{s["url"]}">{E(s["name"])} ↗</a>' if s['url'] else f'<span class="local-label">{E(s["name"])}</span>'
   b+=f'<tr><th scope="row"><span class="step-number">{i+1:02d}</span>{E(label)}</th><td>{value}</td><td>{NOTES[role]}</td></tr>'
  b+='</tbody></table></div></section>'
 b+='<aside class="callout"><strong>Implementation note.</strong> '+EXTRA.get(x['id'],'Keep data preparation, validation, model inference, and orchestration distinct even when they share a deployment.')+'</aside><details><summary>Notation and operational boundaries</summary><ul><li>Rounded block: client, device, or human actor.</li><li>Rectangle: processing or model capability. Diamond: a decision or authorization gate.</li><li>Cylinder: persisted data. Stacked marks: queue or stream.</li><li>Solid arrow: primary data or execution path. Dashed arrow: a control, repeat, or bypass path.</li><li>Dashed enclosure: logical scope, not a shared cloud or network boundary.</li></ul><p>Production deployments also need identity, secrets management, network rules, observability, budgets, deadlines, and failure handling. Follow the linked service documentation and confirm region and model support.</p></details></section>'
 return b

(OUT/'diagrams'/'icon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40"><rect width="40" height="40" rx="6" fill="#174f9d"/><path d="M9 12H31M9 20H31M9 28H31M14 8V32M26 8V32" stroke="white" stroke-width="2"/></svg>')
(OUT/'diagrams'/'atlas.svg').write_text('''<svg xmlns="http://www.w3.org/2000/svg" width="960" height="190" viewBox="0 0 960 190" font-family="Arial,sans-serif" role="img" aria-labelledby="t"><title id="t">Explore a category, understand an architecture, and map it to a cloud</title><defs><marker id="a" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8" fill="#60738b"/></marker></defs><rect width="960" height="190" fill="#f5f8fc"/><g fill="white" stroke="#b9c8de"><rect x="24" y="30" width="270" height="115" rx="5"/><rect x="345" y="30" width="270" height="115" rx="5"/><rect x="666" y="30" width="270" height="115" rx="5"/></g><g fill="#52647a" font-size="11"><text x="44" y="56">01 · BROWSE</text><text x="365" y="56">02 · UNDERSTAND</text><text x="686" y="56">03 · IMPLEMENT</text></g><g fill="#173f78" font-size="20" font-weight="bold"><text x="44" y="88">Category</text><text x="365" y="88">Architecture</text><text x="686" y="88">Cloud mapping</text></g><g fill="#52647a" font-size="13"><text x="44" y="119">Voice, applications, devices…</text><text x="365" y="119">Flows, tradeoffs, failure modes</text><text x="686" y="119">AWS · GCP · Azure</text></g><path d="M297 86H338M618 86H659" stroke="#60738b" stroke-width="2" marker-end="url(#a)"/><text x="24" y="175" fill="#52647a" font-size="12">Shared architectures appear in several categories. Each design has one canonical detail page.</text></svg>''')
body='''<section class="intro"><span class="eyebrow">AI SYSTEM DESIGN / RESEARCH REFERENCE</span><h1>A practical reference for<br>designing AI systems.</h1><p class="lead">Understand the architecture, follow the flow, and map the building blocks to <mark>AWS, Google Cloud, or Azure</mark>.</p><p>Explore conversations, voice assistants, web and desktop applications, device intelligence, and AI that works behind the scenes.</p><div class="intro-links"><a class="button" href="#explore">Browse categories ↓</a><a href="architectures.html">All 20 architectures →</a></div></section><figure class="overview"><img src="diagrams/atlas.svg" width="960" height="190" alt="Three layers of discovery: category, shared architecture, and cloud implementation."></figure><section id="explore"><div class="section-head"><h2>Six ways into the same collection</h2><span class="count-label">20 unique patterns</span></div><p class="muted">Categories overlap. A design can support several experiences and environments.</p><div class="categories">'''
for i,c in enumerate(CATS):
 count=sum(c['id'] in x['categories'] for x in ITEMS)
 body+=f'<article class="card"><span class="eyebrow">CATEGORY {i+1:02d}</span><h3><a href="categories/{c["id"]}/index.html">{c["title"]} →</a></h3><p>{c["description"]}</p><a class="text-link" href="categories/{c["id"]}/index.html">Browse {count} architectures</a></article>'
body+='</div></section><aside class="callout"><strong>How the taxonomy works.</strong> A voice assistant may also run on a phone, use retrieval, and call tools. Categories are entry points; patterns are composable building blocks.</aside><section><div class="section-head"><h2>Start with the foundations</h2><a href="architectures.html">Complete index →</a></div><div class="arch-grid">'+''.join(card(ITEMS[i]) for i in [0,1,6])+'</div></section>'
page('index.html','AI system design reference',body)
for i,c in enumerate(CATS):
 matches=[x for x in ITEMS if c['id'] in x['categories']]
 body=breadcrumb(c['title'],True)+f'<section class="page-heading"><span class="eyebrow">CATEGORY {i+1:02d} · {len(matches)} ARCHITECTURES</span><h1>{c["title"]}</h1><p class="lead">{c["description"]}</p></section><aside class="callout"><strong>Reading path:</strong> open an architecture to study its flow, tradeoffs, failure modes, and AWS, GCP, and Azure service mappings.</aside><section class="arch-grid">'+''.join(card(x,'../../') for x in matches)+'</section><section><h2>Explore another category</h2><div class="category-links">'+''.join(f'<a href="../{a["id"]}/index.html">{a["title"]} →</a>' for a in CATS if a!=c)+'</div></section>'
 page(f'categories/{c["id"]}/index.html',c['title'],body,2)
for i,x in enumerate(ITEMS):
 body=breadcrumb(x['title'])+f'<section class="page-heading"><span class="eyebrow">PATTERN {i+1:02d} · SYSTEM DESIGN</span><h1>{x["title"]}</h1><p class="lead">{x["description"]}</p>'+chips(x,'../../')+'<nav class="article-nav" aria-label="On this page"><a href="#implementation">Cloud diagram & services ↓</a><a href="#analysis">Design analysis ↓</a><a href="#sources">Sources ↓</a></nav></section>'+implementation(x)
 body+='<section id="analysis" class="analysis"><h2>Design analysis</h2><div class="analysis-grid">'
 for label,key,cls in [('WHEN TO USE','fit','fit'),('EXAMPLE','example','example'),('TRADEOFF','tradeoff','tradeoff'),('FAILURE & RECOVERY','failure','failure'),('EVALUATION','evaluation','evaluation')]:
  body+=f'<article class="analysis-note {cls}"><span class="note-label">{label}</span><p>{x[key]}</p></article>'
 body+='</div><details><summary>Production checkpoints</summary><ul><li>Define input contracts and measurable success criteria.</li><li>Check permissions and validate model outputs outside the model.</li><li>Set budgets, deadlines, cancellation, retry limits, and recovery behavior.</li><li>Version models, instructions, and data; evaluate before release and retain a rollback path.</li><li>Minimize sensitive content in traces and define retention policies.</li></ul></details></section><section class="sources" id="sources"><span class="eyebrow">EVIDENCE & FURTHER READING</span><h2>Sources and scope</h2><p>Diagrams, examples, tradeoffs, and service mappings are editorial engineering synthesis. Primary references support the underlying mechanisms; provider documentation is linked beside each cloud service. These are not vendor-certified deployment templates.</p>'+''.join(f'<a href="{SOURCES[k]["url"]}">{SOURCES[k]["title"]} ↗</a>' for k in x['sources'])+'</section>'
 related=sorted((y for y in ITEMS if y!=x),key=lambda y:-len(set(x['categories'])&set(y['categories'])))[:3]
 body+='<section><h2>Related building blocks</h2><div class="arch-grid">'+''.join(card(y,'../../') for y in related)+'</div></section>'
 page(f'architectures/{x["id"]}/index.html',x['title'],body,2)
page('architectures.html','Architecture index','<section class="page-heading"><span class="eyebrow">COMPLETE INDEX</span><h1>AI system architectures</h1><p class="lead">20 composable patterns, each with a system diagram, cloud mappings, design tradeoffs, and evaluation notes.</p></section><section class="arch-grid">'+''.join(card(x) for x in ITEMS)+'</section>')
body='''<section class="page-heading"><span class="eyebrow">METHOD & SOURCES</span><h1>About this reference</h1><p class="lead">A selective map of AI system design, supported by primary documentation and illustrative cloud compositions.</p></section><article class="prose"><h2>Scope and selection</h2><p>The atlas covers application and system patterns: how inputs, models, retrieval, tools, queues, devices, and review stages fit together. It does not attempt to catalog neural network internals such as transformers or diffusion networks. Patterns were selected for broad applicability, not ranked by measured market share.</p><h2>Layered and overlapping</h2><p>The homepage leads to category collections, which lead to shared architecture pages. The six categories mix interaction style, deployment environment, and orchestration as navigational lenses. There are 20 unique patterns; multiple memberships do not create duplicate designs.</p><h2>Interface and activation are separate</h2><p>AI work can begin with a user turn, an event, a stream, or a schedule. An agent may continue after a chat ends. A recommendation system may never expose a conversational interface. Several patterns can coexist in one product.</p><h2>Cloud mappings and notation</h2><p>The cloud buttons switch between AWS, GCP, and Azure diagrams and service tables. Choices are illustrative; they do not imply identical features, region availability, limits, or prices. Custom application code, human judgment, and local device execution are labeled separately.</p><p>Rounded blocks indicate actors, rectangles processing, diamonds decisions, cylinders stored data, and stacked marks queues or streams. Solid arrows trace the primary path; dashed arrows show loops or bypasses. The enclosure is logical scope rather than a cloud network boundary.</p><h2>Research method</h2><p>Core references were reviewed October 20, 2026. This complete distribution was assembled October 22, 2026. Examples, tradeoffs, safeguards, measurements, and compositions are editorial synthesis. Verify each service’s current documentation and evaluate representative workloads before implementation.</p><h2>Primary references</h2>'''
for s in SOURCES.values():body+=f'<div class="source-entry"><h3><a href="{s["url"]}">{s["title"]} ↗</a></h3><p>{s["note"]}</p></div>'
body+='''<h2>Read-only and static</h2><p>All HTML, styles, diagrams, and the small cloud-selection script are self-hosted. The website contains no visitor forms, accounts, cookies, browser storage, tracking, third-party scripts, fonts, or embeds. Changing the cloud selection makes no network requests. With JavaScript disabled, all cloud references remain visible.</p></article>'''
page('about.html','Method and sources',body)
for name in ('style.css','site.js'):shutil.copyfile(ROOT/name,OUT/name)
(OUT/'.nojekyll').touch()
print(f'Built {len(list(OUT.rglob("*.html")))} pages and {len(list((OUT/"diagrams").glob("*.svg")))} self-hosted diagrams.')
